import sys
import math

def find_aiming_point(y1, y2, yw, xb, yb, r):
    # Calculate the angle at which the ball is hit
    theta = math.atan2(yw - yb, xb)

    # Determine the intersection of the ball's trajectory with the goalposts (y1, y2)
    if theta == 0 or theta == math.pi:
        # The ball is heading directly to the goalposts, aiming for the middle
        xw = xb + (y2 - y1) / math.tan(theta)
    else:
        # Calculate the coefficient of the line that the ball's path makes with the x-axis
        if theta > 0:
            # Ball heading towards the right
            x1 = (y2 - yb) / math.tan(theta) + xb
            xw = x1 + (yw - y1) / math.tan(theta)
        else:
            # Ball heading towards the left
            x2 = (y1 - yb) / math.tan(theta) + xb
            xw = x2 + (yw - y1) / math.tan(theta)

    # Check if the calculated aiming point is valid
    if xw < 0:
        return -1

    # Ensure that the ball will bounce once off the wall and enter the goal
    if not (yw - r <= yb <= yw + r):
        return -1

    # Ensure the ball will go into the goal after the bounce
    if not (y1 <= yb <= y2):
        return -1

    return xw

def main():
    input_data = sys.stdin.read().strip()
    y1, y2, yw, xb, yb, r = map(int, input_data.split())
    result = find_aiming_point(y1, y2, yw, xb, yb, r)
    if result == -1:
        print(result)
    else:
        print(f"{result:.12f}")

if __name__ == "__main__":
    main()

def find_robowallace_aim():
    import sys
    input = sys.stdin.read
    data = input().strip().split()

    y1, y2, yw, xb, yb, r = map(int, data)

    # Function to check if a point (x, y) is within the goal posts boundaries
    def in_goalposts(x, y):
        return y1 <= y <= y2

    # Calculate the time it takes for the ball to hit the wall and the goal
    def ball_to_wall_to_goal(xw):
        if xw <= xb:
            return float('inf'), float('inf')

        # Time to hit the wall
        tx = (xw - xb) / 2
        ty = (yw - yb) / 2

        # Calculate where the ball hits the wall after it reflects from xw
        if (yw - yb) ** 2 - 4 * (yw - yb) * (yb - y1) <= 0:
            return float('inf'), float('inf')

        t2 = (yw + yb) / 2 - ((yw + yb) ** 2 - 4 * (yw - yb) * (yb - y1)) ** 0.5 / (2 * (yw - yb))

        if t2 < 0 or t2 > 2 * ty:
            return float('inf'), float('inf')

        xw_after_bounce = xb + 2 * (xw - xb) * (t2 / (2 * tx))
        yw_after_bounce = yb + 2 * (yw - yb) * ((t2 - tx) / tx)

        return xw_after_bounce, yw_after_bounce

    # Initial bounds for binary search
    left, right = xb + r, xb + 1e6

    # Perform binary search for the correct aiming point
    while right - left > 1e-9:
        mid = (left + right) / 2
        xw_after_bounce, yw_after_bounce = ball_to_wall_to_goal(mid)

        if in_goalposts(xw_after_bounce, yw_after_bounce):
            right = mid
        else:
            left = mid

    xw_after_bounce, yw_after_bounce = ball_to_wall_to_goal(right)

    if in_goalposts(xw_after_bounce, yw_after_bounce):
        print(f"{right:.12f}")
    else:
        print("-1")

